//import React, { } from 'react';
import { useEffect ,useState } from 'react';
import { NavLink } from "react-router-dom";
import Search from '../components/Search';

const Dashboard = () => {
const [users,setUsers]=useState([]);
const [user,setUser]=useState("")
const [username,setUsername]=useState("")
const [startingIndex,setStartingIndex]=useState(0);
const [endingIndex, setEndingIndex] = useState(10);

const ShowUser = async () => {
  try{
    let response = await fetch("https://api.github.com/users?per_page=100");
  let userdata = await response.json();
  setUsers(userdata)
  console.log(userdata) 
  }
  catch{
    throw new Error ("Utilisateur introuvable")
  }
};
const addUser = () =>{ 
   setEndingIndex((endingIndex)=>endingIndex+10);
}
const searchUser = async (name) => {
 let response = await fetch(`https://api.github.com/users/${name}`)
 let data = await response.json()
 setUsers([])
 setUser(data)
 console.log(data)
}

 useEffect(() => {
   ShowUser();

 }, []);


    return (
      <>
        <div>
          <form
            className="flex justify-center my-6"
            onSubmit={(e) => {
              e.preventDefault();
              searchUser(username);
            }}
          >
            <input
              type="text"
              placeholder="Rechercher un utilisateur GitHub..."
              className="w-72 p-2 rounded-l-md border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
              onChange={(e) => {
                if (e.target.value === "") {
                  ShowUser();
                }
                setUsername(e.target.value);
                console.log(username);
              }}
            />
            <button
              type="submit"
              className="bg-blue-500 text-white px-4 rounded-r-md hover:bg-blue-600 transition"
            >
              Rechercher
            </button>
          </form>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {users.length > 0 ? (
            users.slice(startingIndex, endingIndex).map((user) => (
              <NavLink to={`/user/${user.login}`}>
                <div
                  key={user.id}
                  className="border rounded p-3 flex flex-col items-center"

                >
                  <img
                    src={user.avatar_url}
                    alt={user.login}
                    className="w-16 h-16 rounded-full"
                  />
                  <p className="mt-2 text-sm font-semibold">{user.login}</p>
                </div>
              </NavLink>
            ))
          ) : (
           <NavLink to={`/user/${user.login}`}>
              <div
                key={user.id}
                className="border rounded p-3 flex flex-col items-center"
              >
                <img
                  src={user.avatar_url}
                  alt={user.login}
                  className="w-16 h-16 rounded-full"
                />
                <p className="mt-2 text-sm font-semibold">{user.login}</p>
              </div>
            </NavLink>
          )}
          {users.length > 0 ? (
            <button
              onClick={() => {
                addUser();
              }}
            >
              Load more
            </button>
          ) : (
            ""
          )}
        </div>
      </>
    );
};

export default Dashboard;

import React from 'react';
import Header from '../components/Header';
import Search from '../components/Search';


const Home = () => {
    return (
        <Header/>  
    );
};

export default Home;

import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";

const UserInfos = () => {
  const { username } = useParams();
  const [selectedUser, setSelectedUser] = useState(null);

  useEffect(() => {
    const fetchUser = async () => {
      const res = await fetch(`https://api.github.com/users/${username}`);
      const data = await res.json();
      setSelectedUser(data);
    };

    fetchUser();
  }, [username]);

  if (!selectedUser) return null;

  return (
    <div className="max-w-xl mx-auto mt-8 p-6 border rounded-lg shadow-lg">
      <div className="flex items-center gap-6">
        <img
          src={selectedUser.avatar_url}
          alt={selectedUser.login}
          className="w-24 h-24 rounded-full"
        />

        <div>
          <h2 className="text-2xl font-bold">
            {selectedUser.name || selectedUser.login}
          </h2>
          <p className="text-gray-600">@{selectedUser.login}</p>
          <p className="mt-2 text-sm text-gray-700">{selectedUser.bio}</p>
        </div>
      </div>

      <div className="grid grid-cols-3 text-center mt-6">
        <div>
          <p className="text-lg font-bold">{selectedUser.public_repos}</p>
          <p className="text-gray-500 text-sm">Repos</p>
        </div>
        <div>
          <p className="text-lg font-bold">{selectedUser.followers}</p>
          <p className="text-gray-500 text-sm">Followers</p>
        </div>
        <div>
          <p className="text-lg font-bold">{selectedUser.following}</p>
          <p className="text-gray-500 text-sm">Following</p>
        </div>
      </div>

      <div className="mt-6 text-sm text-gray-700 space-y-1">
        <p>
          <strong>Entreprise :</strong> {selectedUser.company}
        </p>
        <p>
          <strong>Localisation :</strong> {selectedUser.location}
        </p>
        <p>
          <strong>Blog :</strong>{" "}
          <a
            href={selectedUser.blog}
            target="_blank"
            className="text-blue-500 underline"
          >
            {selectedUser.blog}
          </a>
        </p>
        <p>
          <strong>Compte créé le :</strong>{" "}
          {new Date(selectedUser.created_at).toLocaleDateString()}
        </p>
      </div>
    </div>
  );
};

export default UserInfos;

